terraform {
  required_version = ">= 1.8.2"
}

resource "aws_wafv2_web_acl" "dynamic_example" {
  name        = "managed-rule-example"
  description = "Example with dynamic rules"
  scope       = "REGIONAL"

  default_action {
    allow {}
  }

  # static managed rule as in passing examples
  rule {
    name     = "aws-managed-known-bad-inputs"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "aws-managed-known-bad-inputs"
      sampled_requests_enabled   = true
    }
  }

  # another static rule
  rule {
    name     = "aws-managed-common-rule-set"
    priority = 2

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "aws-managed-common-rule-set"
      sampled_requests_enabled   = true
    }
  }

  # dynamic rule 1
  dynamic "rule" {
    for_each = [1]

    content {
      name     = "ip-allowlist"
      priority = 8

      action {
        allow {}
      }

      statement {
        or_statement {
          statement {
            ip_set_reference_statement {
              arn = "arn:aws:wafv2:us-east-1:123456789012:ipset/example1"
            }
          }
          statement {
            ip_set_reference_statement {
              arn = "arn:aws:wafv2:us-east-1:123456789012:ipset/example2"
            }
          }
        }
      }

      visibility_config {
        cloudwatch_metrics_enabled = true
        metric_name                = "ip-allowlist"
        sampled_requests_enabled   = true
      }
    }
  }

  # dynamic rule 2
  dynamic "rule" {
    for_each = [1]

    content {
      name     = "review-token-check"
      priority = 30

      action {
        allow {}
      }

      statement {
        byte_match_statement {
          positional_constraint = "EXACTLY"
          search_string         = "example-token"

          field_to_match {
            single_header {
              name = "review-token"
            }
          }

          text_transformation {
            priority = 1
            type     = "NONE"
          }
        }
      }

      visibility_config {
        cloudwatch_metrics_enabled = true
        metric_name                = "review-token-check"
        sampled_requests_enabled   = true
      }
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "friendly-metric-name"
    sampled_requests_enabled   = true
  }
}

